        // tw_stock_db客製: Advance設定改版面太長、找不到設定為分頁式（比照
        // web/index.html的#settings-modal .modal-cat/.modal-pane同一套互動模式，
        // 這裡是floating-assistant自己的獨立CSS命名空間ai-advanced-*）。
        // tw_stock_db客製: 2026-09-17——側欄改成_buildAdvancedSettingsSidebarHtml()
        // 動態產生、每次_renderAdvancedSettings()都可能整個重建innerHTML
        // （見該方法說明），原本逐一綁在個別.ai-advanced-cat上的listener
        // 重建後就會消失，改成綁在不會被重建的父層.ai-advanced-sidebar上、
        // 用事件代理（event delegation）處理，同時這裡也一併處理新增的
        // 群組展開/收合標題列點擊。
        const advancedSidebarEl = document.getElementById('ai-advanced-sidebar');
        if (advancedSidebarEl) {
            advancedSidebarEl.addEventListener('click', (event) => {
                const groupHeader = event.target.closest('.ai-advanced-group-header');
                if (groupHeader) {
                    const groupKey = groupHeader.dataset.group;
                    this._advancedSettingsGroupCollapsed[groupKey] = !this._advancedSettingsGroupCollapsed[groupKey];
                    advancedSidebarEl.innerHTML = this._buildAdvancedSettingsSidebarHtml();
                    return;
                }
                const cat = event.target.closest('.ai-advanced-cat');
                if (!cat) return;
                this._advancedSettingsActiveCat = cat.dataset.cat;
                document.querySelectorAll('#ai-advanced-modal .ai-advanced-cat').forEach(c => c.classList.toggle('active', c === cat));
                document.querySelectorAll('#ai-advanced-modal .ai-advanced-pane').forEach(p =>
                    p.classList.toggle('hidden', p.dataset.pane !== cat.dataset.cat)
                );
            });
        }
        document.getElementById('ai-tool-add-btn').onclick = () => this._openToolEditor(-1);
        // tw_stock_db客製: 2026-09-18使用者要求（TODO.md Phase 3第6項）——
        // 見_openToolEditor()裡「➕ 建立新的技能包(Domain)...」選項的說明，
        // 選中這個特殊值時當場跳prompt()問名稱、建立新skill bundle並自動
        // 選中它（MediaWiki風格「打新名稱直接建立」，不用先跳出編輯器）。
        const toolBundleSelect = document.getElementById('ai-tool-skill-bundle-select');
        if (toolBundleSelect) {
            toolBundleSelect.addEventListener('change', () => {
                if (toolBundleSelect.value !== '__create_new__') return;
                const name = (prompt('幫這個新技能包(Domain)取一個名稱：', '') || '').trim();
                if (!name) { toolBundleSelect.value = ''; return; }
                const newId = this._createSkillBundle(name, ''); // 內部已經呼叫過_syncSkillBundleDomains()/_saveAdvancedSettings()
                this._renderSkillBundleList();
                const options = ['<option value="">（未分類）</option>']
                    .concat(this.advancedSettings.skillBundles.map(b => `<option value="${this._escapeHtml(b.id)}">${this._escapeHtml(b.name)}</option>`))
                    .concat(['<option value="__create_new__">➕ 建立新的技能包(Domain)...</option>']);
                toolBundleSelect.innerHTML = options.join('');
                toolBundleSelect.value = newId;
            });
        }
        document.getElementById('ai-skill-export-btn').onclick = () => this._exportSkillZip();
        // tw_stock_db客製: 2026-09-16——「技能包(Skill Bundle)」清單的事件
        // 綁定。編輯知識/人設用一個獨立的小彈窗（不是code editor，純文字），
        // this.activeSkillBundleEditId記住目前正在編輯哪個bundle（-1或空字串
        // 都代表「還沒開始編輯任何一個」，儲存時找不到對應id就直接return，
        // 防禦性寫法避免彈窗殘留舊狀態時誤寫到錯的bundle）。
        document.getElementById('ai-skill-bundle-add-btn').onclick = () => {
            const name = (prompt('幫這個技能包取一個名稱（例如「GPT Codex風格coding skill」）：', '') || '').trim();
            if (!name) return;
            this._createSkillBundle(name, '');
            this._renderSkillBundleList();
            this._log(`✅ 已建立技能包「${name}」，可以點「編輯知識/人設」填入蒸餾出來的知識內容。`);
        };
        const skillBundleList = document.getElementById('ai-skill-bundle-list');
        if (skillBundleList) {
            skillBundleList.addEventListener('click', (event) => {
                const toggleBtn = event.target.closest('[data-skill-bundle-toggle]');
                if (toggleBtn) {
                    const bundle = this.advancedSettings.skillBundles.find(b => b.id === toggleBtn.dataset.skillBundleToggle);
                    if (!bundle) return;
                    bundle.enabled = bundle.enabled === false ? true : false;
                    this._syncSkillBundleDomains();
                    this._saveAdvancedSettings();
                    this._renderSkillBundleList();
                    return;
                }
                const editBtn = event.target.closest('[data-skill-bundle-edit]');
                if (editBtn) {
                    const bundle = this.advancedSettings.skillBundles.find(b => b.id === editBtn.dataset.skillBundleEdit);
                    if (!bundle) return;
                    this.activeSkillBundleEditId = bundle.id;
                    document.getElementById('ai-skill-bundle-name-input').value = bundle.name;
                    document.getElementById('ai-skill-bundle-persona-input').value = bundle.personaPrompt || '';
                    document.getElementById('ai-skill-bundle-editor-modal').style.display = 'flex';
                    return;
                }
                const exportBtn = event.target.closest('[data-skill-bundle-export]');
                if (exportBtn) {
                    this._exportSkillZip(exportBtn.dataset.skillBundleExport);
                    return;
                }
                // tw_stock_db客製: 2026-09-16——單獨刪除某個技能包底下的一個
                // 附加檔案，不用整個bundle重新匯入。key格式是`${bundleId}::${path}`
                // （用第一個`::`切開，因為path本身可能含`/`但不會含`::`）。
                const skillFileDeleteBtn = event.target.closest('[data-skill-file-delete]');
                if (skillFileDeleteBtn) {
                    const key = skillFileDeleteBtn.dataset.skillFileDelete;
                    const sep = key.indexOf('::');
                    if (sep < 0) return;
                    const bundleId = key.slice(0, sep);
                    const path = key.slice(sep + 2);
                    const bundle = this.advancedSettings.skillBundles.find(b => b.id === bundleId);
                    if (!bundle) return;
                    this.skillFileCache.delete(key).catch(() => {});
                    bundle.files = (bundle.files || []).filter(f => f.path !== path);
                    this._syncSkillBundleDomains();
                    this._saveAdvancedSettings();
                    this._renderSkillBundleList();
                    return;
                }
                const deleteBtn = event.target.closest('[data-skill-bundle-delete]');
                if (deleteBtn) {
                    const bundle = this.advancedSettings.skillBundles.find(b => b.id === deleteBtn.dataset.skillBundleDelete);
                    if (!bundle) return;
                    if (!confirm(`刪除技能包「${bundle.name}」？底下的工具不會被刪除，會改回「未分類」狀態；附加的參考資料/腳本檔案會一併刪除。`)) return;
                    // tw_stock_db客製: 2026-09-16——跟工具的非破壞性刪除不同：
                    // 附加檔案是這個技能包專屬的參考資料，沒有「退回未分類、
                    // 被別的技能包重新認領」的使用情境，刪除bundle時一併清掉，
                    // 避免skillFileCache累積永遠沒人再讀得到的孤兒檔案。
                    (bundle.files || []).forEach(f => { this.skillFileCache.delete(`${bundle.id}::${f.path}`).catch(() => {}); });
                    this.advancedSettings.skillBundles = this.advancedSettings.skillBundles.filter(b => b.id !== bundle.id);
                    this.advancedSettings.customTools.forEach(t => { if (t.skillBundleId === bundle.id) t.skillBundleId = null; });
                    this._syncSkillBundleDomains();
                    this._saveAdvancedSettings();
                    this._renderSkillBundleList();
                    this._renderCustomToolList();
                    return;
                }
            });
        }
        const skillBundleEditorModal = document.getElementById('ai-skill-bundle-editor-modal');
