        const perfMaxMeshTrianglesInput = document.getElementById('ai-perf-max-mesh-triangles');
        if (perfMaxMeshTrianglesInput) {
            perfMaxMeshTrianglesInput.addEventListener('input', () => {
                // 0是使用者刻意要的「不限制」，跟fileCacheLimitMB/batchConcurrency
                // 的「n>0才接受」不同，這裡要用n>=0（見_getMaxImportedMeshTriangles/
                // _normalizeAdvancedSettings的同一個決策，維持三處一致）。
                const raw = perfMaxMeshTrianglesInput.value.trim();
                if (raw !== '') {
                    const n = Number(raw);
                    if (Number.isFinite(n) && n >= 0) this.advancedSettings.maxImportedMeshTriangles = Math.round(n);
                }
                this._saveAdvancedSettings();
            });
        }
        const perfMp4DurationInput = document.getElementById('ai-perf-mp4-duration');
        if (perfMp4DurationInput) {
            perfMp4DurationInput.addEventListener('input', () => {
                const n = Number(perfMp4DurationInput.value);
                if (Number.isFinite(n) && n > 0) this.advancedSettings.mp4DefaultDurationSeconds = Math.max(1, Math.round(n));
                this._saveAdvancedSettings();
            });
        }
        // tw_stock_db客製: 2026-09-18使用者要求的xterm Configure分頁——見
        // _createDefaultAdvancedSettings()的terminal欄位/_normalizeTerminalSettings()
        // 說明，這裡統一用一個小helper更新this.advancedSettings.terminal的
